(() => {
 const menu=document.querySelector('#champ-menu');if(!menu)return;
 const logo='<div class="grid-logo" aria-hidden="true"><span class="brand-mark"><i></i><i></i><i></i><i></i></span><strong>EN3.LIVE</strong></div>';
 const labels=['BANDIPUR','VEDA NĀDA','JUNGLE SAFARI','IN CONCERT','FOREST STORIES','LIVE AT THE SOURCE','MORNING DRIVE','LIVING MELODY','WILD ENCOUNTERS','THE PEOPLE BEHIND IT','A FULL HOUSE','FIELD NOTES','YOUR NEXT EXPERIENCE','SHOW UP','DISCOVER MORE','ONE PASS','GOOD TIMES','AT THE SOURCE'];
 menu.innerHTML='<div class="grid-menu"><span class="grid-menu-hint">MOVE THROUGH THE GRID / EN3 LOGO REVEALS</span>'+Array.from({length:72},(_,i)=>'<div class="grid-tile" style="--tile-index:'+i+'">'+logo+'<span>'+labels[i%labels.length]+'</span></div>').join('')+'<a class="grid-cta partner" href="/partners"><small>03</small><span>BECOME A<br>PARTNER</span></a><a class="grid-cta experiences" href="/#whats-on"><small>04</small><span>FIND YOUR<br>NEXT EXPERIENCE</span></a><a class="grid-cta contact" href="/contact"><small>05</small><span>GET IN<br>TOUCH</span></a><div class="grid-bottom"><a href="/gallery/"><i>⠿</i>VISUAL WORLD ↗</a><a href="/blog"><i>⠿</i>JOURNAL ↗</a><a href="/tickets"><i>⠿</i>MY TICKETS ↗</a><a href="/resources/"><i>⠿</i>RESOURCES ↗</a></div></div>';
 const motionControl=document.createElement('button');motionControl.type='button';motionControl.id='grid-motion';const motionOff=document.documentElement.dataset.motion==='reduced';motionControl.innerHTML='<i>'+(motionOff?'▶':'Ⅱ')+'</i>'+(motionOff?'PLAY MOTION':'PAUSE MOTION');motionControl.setAttribute('aria-label',motionOff?'Play design motion':'Pause design motion');menu.querySelector('.grid-bottom').append(motionControl);motionControl.addEventListener('click',()=>{try{localStorage.setItem('en3-design-motion',motionOff?'full':'reduced');}catch{}location.reload();});
 const tiles=[...menu.querySelectorAll('.grid-tile')],timers=new Map();let reduced=document.documentElement.dataset.motion==='reduced',active=-1;
 function light(index){if(index<0||index>=tiles.length)return;let tile=tiles[index];clearTimeout(timers.get(index));tile.classList.add('lit','trail');tile.classList.toggle('white',index%7===0);timers.set(index,setTimeout(()=>tile.classList.remove('lit','trail','white'),reduced?100:1400));}
 menu.addEventListener('pointermove',e=>{const box=menu.getBoundingClientRect(),cols=innerWidth<=800?6:12,rows=innerWidth<=800?8:6;const col=Math.min(cols-1,Math.floor((e.clientX-box.left)/box.width*cols)),row=Math.min(rows-1,Math.floor((e.clientY-box.top)/box.height*rows)),index=row*cols+col;if(index!==active){active=index;light(index);if(!reduced){light(index-1);setTimeout(()=>light(index+cols),80);}}});
 menu.addEventListener('touchstart',e=>{let t=e.touches[0],box=menu.getBoundingClientRect(),cols=6,index=Math.floor((t.clientY-box.top)/box.height*8)*cols+Math.floor((t.clientX-box.left)/box.width*cols);light(index);},{passive:true});
 new MutationObserver(()=>{if(!menu.hidden){active=-1;tiles.forEach(t=>t.classList.remove('seed','lit','trail'));}}).observe(menu,{attributes:true,attributeFilter:['hidden']});
})();
